const items = $input.all();

// Filter posts older than 30 days with high engagement
const thirtyDaysAgo = new Date();
thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

const eligible = items.filter(item => {
  const postDate = new Date(item.json.posted_date);
  const engagement = parseInt(item.json.engagement_score || '0');
  return postDate < thirtyDaysAgo && engagement > 50 && item.json.recycled !== 'true';
});

// Sort by engagement and pick top 3
const topPosts = eligible
  .sort((a, b) => (parseInt(b.json.engagement_score) || 0) - (parseInt(a.json.engagement_score) || 0))
  .slice(0, 3);

return topPosts.map(post => {
  const prefixes = ['Icymi:', 'Throwback:', 'In case you missed it:'];
  const prefix = prefixes[Math.floor(Math.random() * prefixes.length)];
  return {
    json: {
      original_text: post.json.text,
      recycled_text: `${prefix} ${post.json.text}`,
      platform: post.json.platform,
      original_date: post.json.posted_date,
      original_engagement: post.json.engagement_score,
      row_number: post.json.row_number
    }
  };
});
